        #{item}
    


    and mn.ipv_create_uname in
    
        #{item}
    


    and mn.ipv_state in
    
        #{item}
    


    and to_char(mn.ipv_start,'yyyy-MM') = #{request.ipvStart}


    and to_char(mn.ipv_end,'yyyy-MM') = #{request.ipvEnd}


    and to_char(mn.ipv_create_time,'yyyy-MM-dd') = #{request.ipvCreateTime}


    and pro.P_Name in
    
        #{item}
    


