        #{item}
    


    and pro.p_inv_total in
    
        #{item}
    


    and prod.D_Name in
    
        #{item}

        select yea.*, ment.d_name as dName,pro.P_Project_Stage as projectState,pro.p_name as pName,pro.P_Sec_Type as pSecType
        from Inv_Plan_Year yea
        left join pre_project pro on  pro.p_id = yea.p_id
        left join SYS_Department ment on pro.p_Competent_Department = ment.d_id

        

                
                    
                        
                            and likePname(#{params.pName},pro.P_Id)=true
                        
                        
                            and pro.P_Name like concat('%',#{params.pName},'%')
                        
                    
                
                
                    AND
                    EXTRACT(YEAR FROM yea.ipv_start) <= #{strYear} and EXTRACT(YEAR FROM yea.ipv_end) >= #{strYear}
                

                
