mapper.select:
select distinct up.u_name from sys_user up left join SYS_Position_User_P pup on pup.u_id=up.u_id left join SYS_Position_P pp on pp.pp_id=pup.pp_id left join SYS_Department_P dp on dp.pd_id=pp.pd_id where pp.PP_Code=#{params.jbr} and dp.p_id in ( select mn.P_Id from Inv_Complete_Month mn left join Con_Contract con on con.Con_Id = mn.Con_Id left join Pre_Project pro on pro.P_Id=mn.P_Id left join SYS_Company proc on proc.C_Id=pro.P_Construction_Unit left join SYS_Department prod on prod.D_Id=pro.P_Competent_Department left join SYS_Department psd on psd.D_Id=pro.P_Department left join SYS_Department sd on mn.Icm_D_Id=sd.D_ID left join Inv_Plan_Year ipv on ipv.Ipv_Id=mn.Ipv_Id left join Inv_Monthly_Schedule ims on ims.Ipv_Id=ipv.Ipv_Id and ims.Ims_Month=mn.Icm_Reporting_Month
${params.authSql}
) UNION select distinct u.u_name from sys_user u where u.u_id in ( select pro.P_Engineer from Inv_Complete_Month mn left join Con_Contract con on con.Con_Id = mn.Con_Id left join Pre_Project pro on pro.P_Id=mn.P_Id left join SYS_Company proc on proc.C_Id=pro.P_Construction_Unit left join SYS_Department prod on prod.D_Id=pro.P_Competent_Department left join SYS_Department psd on psd.D_Id=pro.P_Department left join SYS_Department sd on mn.Icm_D_Id=sd.D_ID left join Inv_Plan_Year ipv on ipv.Ipv_Id=mn.Ipv_Id left join Inv_Monthly_Schedule ims on ims.Ipv_Id=ipv.Ipv_Id and ims.Ims_Month=mn.Icm_Reporting_Month
${params.authSql}
and pro.P_Engineer is not null )

select mn.*, sd.D_Name as pConstructionUnitName, pro.P_Competent_Department as pCompetentDepartment, pro.P_Department as pDepartment, prod.D_Name as pCompetentDepartmentName, psd.d_name as pDepartmentName, con.Con_id as conId, pro.p_Name as pName, ipv.Ipv_P_Type as ipvPType, ipv.report_table_num as reportTableNum, ipv.Ipv_Construction_stage as ipvConstructionStage, ipv.ipv_construction_status as ipvConstructionStatus, ipv.Ipv_Planned_Investment as ipvPlannedInvestment, ipv.Ipv_Start as planStartTime, ipv.Ipv_End as planEndTime, ipv.p_competent_departments as pCompetentDepartments, ipv.Ipv_Completed as ipvCompleted, pro.P_Build_Model as pBuildModel,
NVL(jbrAgg.all_names, u.u_name) as cjJbr,
( select sum(icm.Icm_Budget_Investment) from Inv_Complete_Month icm where icm.Icm_Reporting_Year < mn.Icm_Reporting_Year and icm.Icm_Reporting_Month='12' ) as icmAllBudgetInv, depAgg.dep_names as pCompetentDepartmentNames from Inv_Complete_Month mn left join Con_Contract con on con.Con_Id = mn.Con_Id left join Pre_Project pro on pro.P_Id=mn.P_Id
left join SYS_Company proc on proc.C_Id=pro.P_Construction_Unit left join SYS_Department prod on prod.D_Id=pro.P_Competent_Department left join SYS_Department psd on psd.D_Id=pro.P_Department left join SYS_Department sd on mn.Icm_D_Id=sd.D_ID left join Inv_Plan_Year ipv on ipv.Ipv_Id=mn.Ipv_Id left join Inv_Monthly_Schedule ims on ims.Ipv_Id=ipv.Ipv_Id and ims.Ims_Month=mn.Icm_Reporting_Month
${params.authSql}
and ipv.ipv_construction_status = #{params.ipvConstructionStatus}
order by mn.${params.sortFiled} ${params.sortType}
order by CAST(ipv.report_table_num AS UNSIGNED) ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
ORDER BY CASE mn.icm_state WHEN 3 THEN 99 ELSE mn.icm_state END, CASE WHEN mn.icm_state = 0 THEN mn.icm_create_time ELSE mn.icm_state_time END DESC

select mn.*, sd.D_Name as pConstructionUnitName, pro.P_Competent_Department as pCompetentDepartment, pro.P_Department as pDepartment, prod.D_Name as pCompetentDepartmentName, psd.d_name as pDepartmentName, con.Con_id as conId, pro.p_Name as pName, ipv.Ipv_P_Type as ipvPType, ipv.report_table_num as reportTableNum, ipv.Ipv_Construction_stage as ipvConstructionStage, ipv.ipv_construction_status as ipvConstructionStatus, ipv.Ipv_Planned_Investment as ipvPlannedInvestment, ipv.Ipv_Start as planStartTime, ipv.Ipv_End as planEndTime, ipv.p_competent_departments as pCompetentDepartments, ipv.Ipv_Completed as ipvCompleted, pro.P_Build_Model as pBuildModel,
NVL(jbrAgg.all_names, u.u_name) as cjJbr,
( select sum(icm.Icm_Budget_Investment) from Inv_Complete_Month icm where icm.Icm_Reporting_Year < mn.Icm_Reporting_Year and icm.Icm_Reporting_Month='12' ) as icmAllBudgetInv, depAgg.dep_names as pCompetentDepartmentNames from Inv_Complete_Month mn left join Con_Contract con on con.Con_Id = mn.Con_Id left join Pre_Project pro on pro.P_Id=mn.P_Id
left join SYS_Company proc on proc.C_Id=pro.P_Construction_Unit left join SYS_Department prod on prod.D_Id=pro.P_Competent_Department left join SYS_Department psd on psd.D_Id=pro.P_Department left join SYS_Department sd on mn.Icm_D_Id=sd.D_ID left join Inv_Plan_Year ipv on ipv.Ipv_Id=mn.Ipv_Id left join Inv_Monthly_Schedule ims on ims.Ipv_Id=ipv.Ipv_Id and ims.Ims_Month=mn.Icm_Reporting_Month
${params.authSql}
and ipv.ipv_construction_status = #{params.ipvConstructionStatus}
order by mn.${params.sortFiled} ${params.sortType}
order by TO_NUMBER(ipv.report_table_num) ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
ORDER BY CASE mn.icm_state WHEN 3 THEN 99 ELSE mn.icm_state END, CASE WHEN mn.icm_state = 0 THEN mn.icm_create_time ELSE mn.icm_state_time END DESC

select

sd.D_Name as ipvDName, con.Con_Name as conName, cany.c_name as ipvCName,
depAgg.dep_names as pCompetentDepartmentNames,
mn.*
from Inv_Plan_Year mn


left join SYS_Department sd on mn.Ipv_D_Id=sd.D_ID
left join Con_Contract con on con.Con_Id = mn.Con_Id
left join SYS_Company cany on mn.Ipv_C_id = cany.c_Id

    
        
    
    
        and mn.Te_Id = #{params.teId}
    
    
        and mn.Ipv_D_Id = #{params.ipvDId}
    
    
        and mn.Ipv_Declare_Year = #{params.ipvDeclareYear}
    
    
        and mn.Ipv_Const_Status = #{params.ipvConstStatus}
    
    
        and mn.Ipv_Library = #{params.ipvLibrary}
    
    
        and mn.P_Id = #{params.pId}
    
    
        and mn.Ipv_State = #{params.ipvState}
    
    
        
            
                and likeCname(#{params.ipvCName},cany.C_Id)=true
            
            
                and cany.c_name like concat('%',#{params.ipvCName},'%')
            
        
    
    
        and mn.Ipv_Newly = #{params.ipvNewly}
    
    
        and mn.Ipv_P_Type = #{params.ipvPType}
    
    
        and mn.Ipv_Completed = #{params.ipvCompleted}
    
    
        and pro.P_Competent_Department = #{params.pCompetentDepartment}
    
    
        
            
                and likePname(#{params.pName},pro.P_Id)=true
            
            
                and pro.P_Name like concat('%',#{params.pName},'%')
            
        
    
    
        and con.con_name like concat('%',#{params.conName},'%')
    
    
        and pro.P_Name like concat('%', #{params.projectName}, '%')
    
    
        and con.con_name like concat('%', #{params.contractName}, '%')
    
    
        and mn.Ipv_State!=3 and mn.Ipv_State!=0
    
    
        and mn.ipv_construction_status = #{params.ipvConstructionStatus}
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Ipv_Create_Time DESC
